package com.shopstream.session;

import java.time.Duration;
import java.util.Optional;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

@Component
public class SessionStore {

    private static final Duration IDLE_TIMEOUT = Duration.ofMinutes(30);

    private final StringRedisTemplate redis;

    public SessionStore(StringRedisTemplate redis) {
        this.redis = redis;
    }

    public void create(String sessionId, String userId) {
        // value and TTL in one atomic command: SET key value EX seconds
        redis.opsForValue().set("session:" + sessionId, userId, IDLE_TIMEOUT);
    }

    public Optional<String> touch(String sessionId) {
        // GETEX: read the value and slide the expiry in a single round trip
        String userId = redis.opsForValue()
                .getAndExpire("session:" + sessionId, IDLE_TIMEOUT);
        return Optional.ofNullable(userId);
    }

    public void destroy(String sessionId) {
        redis.delete("session:" + sessionId);
    }
}

package com.shopstream.cache;
import java.time.Duration;
import java.util.concurrent.ThreadLocalRandom;
public final class TtlJitter {
    private TtlJitter() {
    }
    /** Returns base plus a random 0..20 percent, so entries written together expire apart. */
    public static Duration withJitter(Duration base) {
        long extra = (long) (base.toMillis() * 0.2 * ThreadLocalRandom.current().nextDouble());
        return base.plusMillis(extra);
    }
}

package com.shopstream.demo;

import io.lettuce.core.LettuceFutures;
import io.lettuce.core.RedisFuture;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.api.async.RedisAsyncCommands;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;

public class PipelineExample {

    public static List<String> loadStock(StatefulRedisConnection<String, String> conn,
                                         List<String> skus) {
        RedisAsyncCommands<String, String> async = conn.async();
        conn.setAutoFlushCommands(false);
        List<RedisFuture<String>> futures = new ArrayList<>();
        try {
            for (String sku : skus) {
                futures.add(async.get("stock:" + sku));
            }
            conn.flushCommands();                      // one write for all commands
            LettuceFutures.awaitAll(Duration.ofSeconds(2),
                    futures.toArray(new RedisFuture[0]));
        } finally {
            conn.setAutoFlushCommands(true);
        }
        List<String> result = new ArrayList<>();
        for (RedisFuture<String> f : futures) {
            try {
                result.add(f.get());
            } catch (Exception e) {
                throw new IllegalStateException(e);
            }
        }
        return result;
    }
}

package com.shopstream.demo;

import io.lettuce.core.RedisClient;
import io.lettuce.core.TrackingArgs;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.support.caching.CacheAccessor;
import io.lettuce.core.support.caching.CacheFrontend;
import io.lettuce.core.support.caching.ClientSideCaching;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class ClientCacheExample {

    public static void main(String[] args) {
        RedisClient client = RedisClient.create("redis://localhost:6379");
        StatefulRedisConnection<String, String> connection = client.connect();

        Map<String, String> local = new ConcurrentHashMap<>();
        CacheFrontend<String, String> frontend = ClientSideCaching.enable(
                CacheAccessor.forMap(local), connection, TrackingArgs.Builder.enabled());

        String first = frontend.get("product:77:name");   // network, then cached locally
        String second = frontend.get("product:77:name");  // served from the local map
        System.out.println(first + " " + second);

        frontend.close();
        connection.close();
        client.shutdown();
    }
}
